from typing import List, Dict, Any, Optional, Callable
from leann.api import SearchResult
from leann.metadata_filter import MetadataFilterEngine
from collections import defaultdict

def aggregate_search_results(
    search_results: List[SearchResult],
    group_by_field: str,
    aggregation_funcs: Optional[Dict[str, Callable]] = None
) -> Dict[str, Dict[str, Any]]:
    """Aggregate search results by a metadata field with optional statistics.

    Args:
        search_results: List of SearchResult objects to aggregate
        group_by_field: Metadata field name to group by
        aggregation_funcs: Optional dictionary mapping field_name to aggregation function.
            Example: {"score": max, "count": len}
            If None, defaults to count and average score per group

    Returns:
        Dictionary mapping group_value to aggregated statistics
        Example: {"tech": {"count": 5, "avg_score": 0.85, "max_score": 0.95}}
    """
    # Group results by the specified field
    grouped_results = defaultdict(list)

    for result in search_results:
        # Get the metadata field value, default to 'unknown' if missing
        field_value = result.metadata.get(group_by_field)
        if field_value is None:
            field_value = 'unknown'
        else:
            # Convert to string to use as dictionary key
            field_value = str(field_value)

        grouped_results[field_value].append(result)

    # Calculate statistics for each group
    aggregated_stats = {}

    for group_value, results in grouped_results.items():
        stats = {}

        if aggregation_funcs:
            # Use custom aggregation functions
            for stat_name, agg_func in aggregation_funcs.items():
                if stat_name == "count":
                    # Apply to results list
                    stats[stat_name] = agg_func(results)
                elif "score" in stat_name:
                    # Apply to scores
                    scores = [r.score for r in results]
                    stats[stat_name] = agg_func(scores)
                else:
                    # Try to apply to metadata field with same name
                    values = [r.metadata.get(stat_name) for r in results if stat_name in r.metadata]
                    if values:
                        stats[stat_name] = agg_func(values)
        else:
            # Use default statistics
            scores = [r.score for r in results]
            stats = {
                "count": len(results),
                "avg_score": sum(scores) / len(scores) if scores else 0,
                "max_score": max(scores) if scores else 0,
                "min_score": min(scores) if scores else 0
            }

        aggregated_stats[group_value] = stats

    return aggregated_stats

